#!/usr/bin/env python3

import time
import os

# Create a list to store file objects and prevent garbage collection
class FileOpener:
    def __init__(self, filename="/tmp/testfile.txt", max_files=1000):
        self.filename = filename
        self.max_files = max_files
        self.file_objects = []

        # Ensure the file exists
        if not os.path.exists(self.filename):
            with open(self.filename, 'w') as f:
                f.write("Test file for file descriptor experiment\n")

    def open_files_in_loop(self):
        """Open the same file repeatedly and store file objects in a list"""
        counter = 0

        # Create the test file if it doesn't exist
        if not os.path.exists(self.filename):
            with open(self.filename, 'w') as f:
                f.write("Test file for file descriptor experiment\n")

        print(f"Starting to open {self.filename} repeatedly...")
        print("Press Ctrl+C to stop")

        try:
            while True:
                try:
                    # Open the file and append the file object to our list
                    file_obj = open(self.filename, 'r')
                    self.file_objects.append(file_obj)

                    counter += 1
                    if counter % 100 == 0:
                        print(f"Opened file {counter} times. Current file objects count: {len(self.file_objects)}")

                    # Small delay to prevent overwhelming the system
                    time.sleep(0.01)

                except MemoryError:
                    print(f"Memory error after opening file {counter} times")
                    break

        except KeyboardInterrupt:
            print(f"\nStopped by user after opening file {counter} times")
            print(f"File objects stored in list: {len(self.file_objects)}")

        return counter

    def cleanup(self):
        """Clean up all open file objects"""
        print(f"Cleaning up {len(self.file_objects)} file objects...")
        for i, file_obj in enumerate(self.file_objects):
            try:
                file_obj.close()
            except:
                pass  # Ignore errors during cleanup
        self.file_objects.clear()
        print("Cleanup completed")

if __name__ == "__main__":
    # Create file opener instance
    opener = FileOpener()

    try:
        # Run the loop
        count = opener.open_files_in_loop()
    finally:
        # Ensure cleanup happens even if interrupted
        opener.cleanup()
